{"command": "cat > /workspace/build/mks2.py << 'PYEOF'
"""Original sound material synthesis for the keygen tune (pure NumPy)."""
import numpy as np, os, wave, json
SR=44100
OUT='/workspace/samples'; os.makedirs(OUT,exist_ok=True)
rng=np.random.RandomState(01071985)

PC={'C':1,'C#':2,'D':3,'D#':4,'E':5,'F':6,'F#':7,'G':8,'G#':9,'A':10,'A#':11,'B':12}
def idx(name):
    n=name[:-2]; o=int(name[-1]); return 12*o+PC[n]
def im_to_name(i):
    inv={v:k for k,v in PC.items()}
    o=(i-1)//12; n=inv[((i-1)%12)+1]; return "%s-%d"%(n,o)
def freq(i): return 440*2**((i-70)/12.0)

def save(name,x,peak=0.9):
    x=np.asarray(x,float); m=np.max(np.abs(x)) or 1.0
    x=x/m*peak
    xi=np.int16(np.clip(np.round(x*32767),-32768,32767))
    with wave.open(os.path.join(OUT,name+'.wav'),'wb') as f:
        f.setnchannels(1); f.setsampwidth(2); f.setframerate(SR)
        f.writeframes(xi.tobytes())
    return xi.size

def lpf(x,c):
    y=np.empty_like(x); a=0.0
    for i in range(x.size):
        a+=c*(x[i]-a); y[i]=a
    return y
def hpf(x,c): return x-lpf(x,c)
def svf_band(x,f0,Q):
    f0=float(np.clip(f0,20,SR*0.45)); Q=float(np.clip(Q,0.5,4))
    F=min(2*np.sin(np.pi*f0/SR),0.9); d=max(1/Q,1.0)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band+=F*high
        low+=F*band
        out[i]=band
    return out
def svf_low(x,f0,res=0.3):
    f0=float(np.clip(f0,20,SR*0.45))
    F=min(2*np.sin(np.pi*f0/SR),0.9); d=2*(1-res)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band+=F*high
        low+=F*band
        out[i]=low
    return out
def noise(n): return rng.randn(n)

# ---------- periodic tone builder with settling ----------
def tone_loop(noteindex, harm, ops=None, nsub=1, keep_periods=4, settle=60):
    """harm: dict k -> amp  (k may be half-integer when nsub=2)
       ops: list of ('lp',c) ('hp',c) ('tanh',g) ('bp',f0,Q) ('shim',amt)
       returns (looparray, looplen)"""
    P=int(round(SR/freq(noteindex)))
    L=P*nsub
    nper=settle+keep_periods
    tt=np.arange(nper*L)
    x=np.zeros(tt.size)
    for k,a in harm.items():
        x+=a*np.sin(2*np.pi*k*tt/L)
    for op in (ops or []):
        kind=op[0]
        if kind=='lp': x=lpf(x,op[1])
        elif kind=='lp2': x=lpf(lpf(x,op[1]),op[1])
        elif kind=='hp': x=hpf(x,op[1])
        elif kind=='bp': x=svf_band(x,op[1],op[2])
        elif kind=='lpl': x=svf_low(x,op[1],op[2] if len(op)>2 else 0.3)
        elif kind=='tanh': x=np.tanh(op[1]*x)
        elif kind=='soft': x=np.clip(x,-1,1)
    loop=x[(nper-keep_periods)*L:].copy()
    # remove residual DC
    loop-=loop.mean()
    return loop, L

def assemble(loop, head_periods=1, attack=0.006, curve=0.6):
    nhead=int(attack*SR)
    hp=np.tile(loop[:loop.size//len(loop) if False else loop.size],0)
    base=loop.copy()
    # head: first cycle of loop scaled up
    seg=base[:min(base.size,nhead)]
    g=np.linspace(0,1,seg.size)**curve
    head=seg*g
    full=np.concatenate([head, base])
    return full, head.size, base.size

def shot(dur, build, fade=0.003, peak=0.9):
    t=np.arange(int(dur*SR))/SR
    x=build(t)
    nf=min(int(fade*SR), x.size//2)
    if nf>0:
        x[:nf]*=np.linspace(0,1,nf); x[-nf:]*=np.linspace(1,0,nf)
    return x

# ---------- DRUMS ----------
def make_kick():
    def b(t):
        f0=190.0; fend=46.0; k=16.0
        ph=2*np.pi*(fend*t+(f0-fend)/k*(1-np.exp(-k*t)))
        body=np.sin(ph)*np.exp(-t/0.09)
        cl=lpf(np.diff(np.concatenate([[0.0],noise(t.size)])),0.4)
        return body+0.5*cl*np.exp(-t/0.005)+0.22*np.sin(2*np.pi*780*t)*np.exp(-t/0.012)
    return save('kick', shot(0.20,b), 0.97)

def make_snare():
    def b(t):
        nz=noise(t.size)
        s=svf_band(nz,1900,0.8)+0.5*svf_band(nz,3800,1.0)
        tone=np.sin(2*np.pi*196*t)*0.55*np.exp(-t/0.03)+np.sin(2*np.pi*311*t)*0.30*np.exp(-t/0.045)
        return 1.25*s*np.exp(-t/0.085)+tone+0.25*np.sign(nz)*np.exp(-t/0.018)
    return save('snare', shot(0.36,b), 0.88)

def make_clap():
    def b(t):
        nz=noise(t.size)
        s=svf_band(nz,1250,0.75)+0.4*svf_band(nz,2500,1.0)
        out=np.zeros_like(t)
        for off,amp in [(0.0,1.0),(0.010,0.9),(0.021,0.75),(0.034,0.95)]:
            d=np.maximum(t-off,0)
            out+=amp*s*np.exp(-d/0.05)*(t>=off)
        return out+0.3*np.sin(2*np.pi*920*t)*np.exp(-t/0.035)
    return save('clap', shot(0.34,b), 0.85)

def make_hats():
    def bhat(dur,dec,f1,f2,mix):
        def b(t):
            nz=noise(t.size)
            return (svf_band(nz,f1,0.9)+mix*svf_band(nz,f2,1.1))*np.exp(-t/dec)
        return shot(dur,b)
    a=save('hatc',bhat(0.075,0.011,8600,13000,0.6),0.5)
    c=save('fato',bhat(0.45,0.11,6900,10500,0.7),0.5)
    d=save('shaker',bhat(0.16,0.035,5200,9500,0.9),0.4)
    return a,c,d

def make_tom():
    def b(t):
        f=210*np.exp(-t/0.14)+92
        ph=2*np.pi*np.cumsum(f)/SR
        nz=svf_band(noise(t.size),2400,1.0)
        return np.sin(ph)*np.exp(-t/0.17)+0.16*nz*np.exp(-t/0.05)
    return save('tom', shot(0.5,b), 0.8)

def make_riser():
    def b(t):
        nz=noise(t.size)
        out=np.zeros_like(t)
        nch=64; step=t.size//nch
        for c in range(nch):
            a=c*step; z=min(t.size,(c+1)*step)
            seg=nz[a:z]
            out[a:z]+=svf_band(seg,300+4300*((a/t.size)**1.7),0.8)
        swell=(t/t.max())**1.7
        f=180+1100*(t/t.max())**2
        tone=np.sin(2*np.pi*np.cumsum(f)/SR)*0.35
        return (out+tone)*swell
