"""Original sound material synthesis for the keygen tune (pure NumPy)."""
import numpy as np, os, wave, json
SR=44100
OUT='/workspace/samples'; os.makedirs(OUT,exist_ok=True)
rng=np.random.RandomState(01071985)

PC={'C':1,'C#':2,'D':3,'D#':4,'E':5,'F':6,'F#':7,'G':8,'G#':9,'A':10,'A#':11,'B':12}
def idx(name):
    n=name[:-2]; o=int(name[-1]); return 12*o+PC[n]
def im_to_name(i):
    inv={v:k for k,v in PC.items()}
    o=(i-1)//12; n=inv[((i-1)%12)+1]; return "%s-%d"%(n,o)
def freq(i): return 440*2**((i-70)/12.0)

def save(name,x,peak=0.9):
    x=np.asarray(x,float); m=np.max(np.abs(x)) or 1.0
    x=x/m*peak
    xi=np.int16(np.clip(np.round(x*32767),-32768,32767))
    with wave.open(os.path.join(OUT,name+'.wav'),'wb') as f:
        f.setnchannels(1); f.setsampwidth(2); f.setframerate(SR)
        f.writeframes(xi.tobytes())
    return xi.size

def lpf(x,c):
    y=np.empty_like(x); a=0.0
    for i in range(x.size):
        a+=c*(x[i]-a); y[i]=a
    return y
def hpf(x,c): return x-lpf(x,c)
def svf_band(x,f0,Q):
    f0=float(np.clip(f0,20,SR*0.45)); Q=float(np.clip(Q,0.5,4))
    F=min(2*np.sin(np.pi*f0/SR),0.9); d=max(1/Q,1.0)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band+=F*high
        low+=F*band
        out[i]=band
    return out
def svf_low(x,f0,res=0.3):
    f0=float(np.clip(f0,20,SR*0.45))
    F=min(2*np.sin(np.pi*f0/SR),0.9); d=2*(1-res)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band+=F*high
        low+=F*band
        out[i]=low
    return out
def noise(n): return rng.randn(n)

# ---------- periodic tone builder with settling ----------
def tone_loop(noteindex, harm, ops=None, nsub=1, keep_periods=4, settle=60):
    """harm: dict k -> amp  (k may be half-integer when nsub=2)
       ops: list of ('lp',c) ('hp',c) ('tanh',g) ('bp',f0,Q) ('shim',amt)
       returns (looparray, looplen)"""
    P=int(round(SR/freq(noteindex)))
    L=P*nsub
    nper=settle+keep_periods
    tt=np.arange(nper*L)
    x=np.zeros(tt.size)
    for k,a in harm.items():
        x+=a*np.sin(2*np.pi*k*tt/L)
    for op in (ops or []):
        kind=op[0]
        if kind=='lp': x=lpf(x,op[1])
        elif kind=='lp2': x=lpf(lpf(x,op[1]),op[1])
        elif kind=='hp': x=hpf(x,op[1])
        elif kind=='bp': x=svf_band(x,op[1],op[2])
        elif kind=='lpl': x=svf_low(x,op[1],op[2] if len(op)>2 else 0.3)
        elif kind=='tanh': x=np.tanh(op[1]*x)
        elif kind=='soft': x=np.clip(x,-1,1)
    loop=x[(nper-keep_periods)*L:].copy()
    # remove residual DC
    loop-=loop.mean()
    return loop, L

def assemble(loop, head_periods=1, attack=0.006, curve=0.6):
    nhead=int(attack*SR)
    hp=np.tile(loop[:loop.size//len(loop) if False else loop.size],0)
    base=loop.copy()
    # head: first cycle of loop scaled up
    seg=base[:min(base.size,nhead)]
    g=np.linspace(0,1,seg.size)**curve
    head=seg*g
    full=np.concatenate([head, base])
    return full, head.size, base.size

def shot(dur, build, fade=0.003, peak=0.9):
    t=np.arange(int(dur*SR))/SR
    x=build(t)
    nf=min(int(fade*SR), x.size//2)
