def make_kick():
    def b(t):
        f0=190.0; fend=46.0; k=16.0
        ph=2*np.pi*(fend*t+(f0-fend)/k*(1-np.exp(-k*t)))
        body=np.sin(ph)*np.exp(-t/0.09)
