            seg=nz[a:z]
            out[a:z]+=svf_band(seg,300+4300*((a/t.size)**1.7),0.8)
        swell=(t/t.max())**1.7
        f=180+1100*(t/t.max())**2
        tone=np.sin(2*np.pi*np.cumsum(f)/SR)*0.35
        return (out+tone)*swell
    return save('riser', b(np.arange(int(3.2*SR))/SR)*np.hanning(int(3.2*SR)*1.0)*0+save_dummy() if False else save('riser', b(np.arange(int(3.2*SR))/SR),0.75))

def make_crash():
    def b(t):
        nz=noise(t.size)
        s=svf_band(nz,5200,0.6)+0.6*svf_band(nz,9000,0.8)+lpf(nz,0.08)
        e=np.exp(-t/0.75)*(1+0.4*np.sin(2*np.pi*3.2*t))
        return s*e+0.2*np.sin(2*np.pi*1350*t)*np.exp(-t/0.4)
    return save('crash', shot(2.2,b,0.006), 0.6)

def save_dummy(): return 0
