"""Final sample material: static periodic waveforms + synthesized percussion.
   All tonal loops share base period P=531 so every instrument stays in tune with
   the engine law  f = f_file * 2^((note-61)/12)."""
import numpy as np, os, wave, json
SR=44100.0
OUT='/workspace/samples'; os.makedirs(OUT,exist_ok=True)
rng=np.random.RandomState(20240107)
P=531                      # samples per cycle of the A-3 layer
BASS=165                   # bass/sync layer: P/2 -> A-2
def save(name,x,peak=0.9):
    x=np.asarray(x,float); m=np.max(np.abs(x)) or 1.0
    xi=np.int16(np.clip(np.round(x/m*peak*32767),-32768,32767))
    with wave.open(os.path.join(OUT,name+'.wav'),'wb') as f:
        f.setnchannels(1);f.setsampwidth(2);f.setframerate(int(SR));f.writeframes(xi.tobytes())
    return int(xi.size)
def lpf(x,c):
    y=np.empty_like(x); a=0.0
    for i in range(x.size):
        a+=c*(x[i]-a); y[i]=a
    return y
def hpf(x,c): return x-lpf(x,c)
def svf_low(x,f0,res=0.4):
    F=min(2*np.sin(np.pi*float(np.clip(f0,20,SR*0.45))/SR),0.9); d=2*(1-res)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band=F*high+band; low=F*band+low; out[i]=low
    return out
def svf_band(x,f0,Q=0.8):
    F=min(2*np.sin(np.pi*float(np.clip(f0,20,SR*0.45))/SR),0.9); d=1.0/max(Q,0.5)
    low=0.0; band=0.0; out=np.empty_like(x)
    for i in range(x.size):
        high=x[i]-low-d*band
        band=F*high+band; low=F*band+low; out[i]=band*0.6
    return out
def noise(n): return rng.randn(n)

def steady(harm, period, ops=None, cycles=40, settle=6, phases=None):
    """static periodic wave with exact integer period; returns one clean cycle"""
    tt=np.arange(cycles*period)
    x=np.zeros(tt.size)
    for k,a in harm.items():
        if a: x+=a*np.sin(2*np.pi*k*tt/period+(phases or {}).get(k,0.0))
    for op in (ops or []):
        kind=op[0]
        if kind=='lp': x=lpf(x,op[1])
        elif kind=='hp': x=hpf(x,op[1])
        elif kind=='tanh': x=np.tanh(op[1]*x)
        elif kind=='lpl': x=svf_low(x,op[1],op[2] if len(op)>2 else 0.4)
        elif kind=='bp': x=svf_band(x,op[1],op[2] if len(op)>2 else 0.8)
    nc=cycles-settle
    loop=x[settle*period:][:nc*period].reshape(nc,period).mean(0)
    loop-=loop.mean()
    return loop

def mixcycles(*pairs):
    n=min(p.size for p,_ in pairs)
    return sum(p*w for p,w in pairs)[:n]

def loopfile(name, loop, period, ncyc, peak=0.9):
    sig=np.tile(loop,ncyc)
    return dict(name=name, len=save(name,sig,peak), ls=0, ll=int(np.tile(loop,ncyc).size),
                period=period, rel=0, baseidx=None)
