import sys; sys.path.insert(0,'/workspace/build')
from song import *

# instrument numbers
INST={'kick':1,'snare':2,'hatc':3,'fato':4,'clap':5,'shak':6,'tom':7,'ltom':8,'hit':9,
      'crash':10,'riser':11,'bass':12,'sub':13,'sync':14,'steel':15,'harpsi':16,'pad':17,
      'lead':18,'soft':19,'stab':20,'arp':21,'swell':22}
CHAN={'kick':0,'snare':1,'hatc':2,'fato':3,'clap':4,'shak':5,'tom':6,'bass':7,'sub':8,
      'steel':9,'harpsi':10,'pad1':11,'pad2':12,'lead':13,'lead2':14,'fx':15}
CHINST={'kick':'kick','snare':'snare','hatc':'hatc','fato':'fato','clap':'clap','shak':'shak',
        'tom':'tom','bass':'bass','sub':'sub','steel':'steel','harpsi':'harpsi','pad1':'pad',
        'pad2':'pad','lead':'lead','lead2':'soft','fx':'crash'}
ROWS=12; HALF=ROWS*2

class Pat:
    def __init__(self,rows=HALF):
        self.rows=rows; self.cells=[]
    def set(self,row,ch,note,inst,v,off=None):
        self.cells.append((row,ch,note,inst,v))
        if off is not None:
            self.cells.append((min(row+off,self.rows-1),ch,97,0,0))

def V(amp,inst):
    return vol(amp,TRIM.get(inst,1.0))

def drums_bar(p, bar, spec):
    """spec: dict ch-> key of DRUMS or list per bar"""
    for ch,key in spec.items():
        if not key: continue
        k=key if isinstance(key,str) else key[bar%len(key)]
        if not k: continue
        for r,v in DRUMS[k]:
            inst=CHINST[ch]
            p.set(r + (0 if bar==0 else ROWS), CHAN[ch], 96, INST[inst], V(v,inst))

def bass_bar(p, bar, prog, style, amp, inst='bass', ch='bass', dur=None):
    for r,n,v in bass_walk(prog,bar,style):
        a=V(amp*(v/50.0),inst)
        d=dur if dur else None
        p.set(r+(bar*ROWS), CHAN[ch], n, INST[inst], a, off=(d or 2))
def sub_bar(p, bar, prog, style, amp):
    for r,n,v in bass_sub(prog,bar,style):
        p.set(r+(bar*ROWS), CHAN['sub'], n, INST['sub'], V(amp,'sub'), off=ROWS-r-1)

def pad_bar(p, bar, prog, voic, amp1, amp2, inst_dur=ROWS-1, ch1='pad1', ch2='pad2'):
    ns=pad_voicing(prog,bar,voic)
    for j,n in enumerate(ns):
        a=amp1 if j==0 else amp2
        ch=ch1 if j==0 else ch2
        p.set(bar*ROWS, CHAN[ch], n, INST['pad'], V(a,'pad'), off=inst_dur)

def arp_bar(p, bar, prog, kind, shape, octv, amp, ch, inst):
    ev = arp_shape(prog,bar,shape,octv) if kind=='16' else arp_8th(prog,bar,shape,octv)
    for r,n,v in ev:
        p.set(bar*ROWS+r, CHAN[ch], n, INST[inst], V(amp*(v/42.0),inst), off=1)

def lead_bar(p, bar, prog, mel, amp, ch, inst, transpose=0, dur_adj=0):
    for r,n,d in lead_events(prog,mel,bar,transpose):
