        if off is not None:
            self.cells.append((min(row+off,self.rows-1), ch if isinstance(ch,str) else CHS[ch][0],97,0,0))
P=[Pat() for _ in range(NPAT)]
def loc(b): return b%2
def pat(b): return b//2
def note_cell(b): return P[pat(b)]

# ---------- layers ----------
def drums(bars, spec):
    for b,k in bars:
        p=note_cell(b); off=loc(b)*ROWS
        for ch,key in k.items():
            if not key: continue
            kk = key if isinstance(key,str) else key[off//ROWS % len(key)] if isinstance(key,list) else key
            inst=CHIN[ch]
            for r,v in (DRUMS[kk] if isinstance(kk,str) else kk):
                p.note(off+r, CHAN[ch], 96, INST[inst], V(v,inst))
def bass(bars, prog, style, amp, inst='bass'):
    for b in bars:
        p=note_cell(b); off=loc(b)*ROWS
        st = style[b%len(style)] if isinstance(style,list) else style
        for r,n,v in bass_walk(prog,b%8,st):
            p.note(off+r, CHAN['bass'], n, INST[inst], V(amp*v/50.0,inst), off=2)
