{"command": "cd /workspace/build && python3 - << 'EOF'
import sys; sys.path.insert(0,'/workspace/build')
import build_module as B, song
names=[n for n,_ in B.CHS]
lo=999; hi=-1; bad=[]
per={}
for pi,p in enumerate(B.P):
    for (r,ch,n,i,v) in p.cells:
        if n in (0,97) or i==0: continue
        nm=names[ch]
        inst=B.CHS[ch][1]
        isdrum = inst in ('kick','snare','clap','hatc','fato','shak','crash','riser','swell')
        if not isdrum:
            lo=min(lo,n); hi=max(hi,n)
            per.setdefault(nm,(999,-1))
            per[nm]=(min(per[nm][0],n),max(per[nm][1],n))
