print("pitch range (tonal): idx %d (%s) .. %d (%s)"%(lo,song.nm(lo),hi,song.nm(hi)))
for k,v in sorted(per.items()): print("   %-7s %s .. %s"%(k,song.nm(v[0]),song.nm(v[1])))
print("out-of-range notes:",bad[:5], len(bad))
EOF"}

